"use client";

import * as React from "react";
import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { cardSlab, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Burnished Accordion: a stack of questions cut into one umber slab with a
 * 1.5rem corner, each row divided from the next by a dark hairline.
 */
const Accordion = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Root.Props>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Root
    ref={ref}
    data-slot="accordion"
    className={cn("w-full rounded-2xl px-5", cardSlab, className)}
    {...props}
  />
));
Accordion.displayName = "Accordion";

/** Burnished AccordionItem: one row, divided from the next by a hairline. */
const AccordionItem = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Item.Props>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item
    ref={ref}
    data-slot="accordion-item"
    className={cn("border-b border-border last:border-b-0", className)}
    {...props}
  />
));
AccordionItem.displayName = "AccordionItem";

/**
 * Burnished AccordionTrigger: the question in semibold, with a caret at the
 * end that turns over as the answer opens.
 */
const AccordionTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<AccordionPrimitive.Trigger.Props>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Header data-slot="accordion-header" className="flex">
    <AccordionPrimitive.Trigger
      ref={ref}
      data-slot="accordion-trigger"
      className={cn(
        "group/trigger flex flex-1 items-center justify-between gap-3 rounded-md py-4 text-start",
        "text-[0.9375rem] font-semibold tracking-[0.016em] text-foreground",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      {children}
      <Icon
        icon="ph:caret-down"
        aria-hidden="true"
        className="size-4 shrink-0 text-muted-foreground transition-transform duration-base ease-(--ease-out) group-data-[panel-open]/trigger:rotate-180"
      />
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
));
AccordionTrigger.displayName = "AccordionTrigger";

/**
 * Burnished AccordionContent: the answer in muted ink. The panel grows to
 * its measured height on the soft ease-out.
 */
const AccordionContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Panel.Props>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Panel
    ref={ref}
    data-slot="accordion-content"
    className={cn(
      "h-(--accordion-panel-height) overflow-hidden text-sm leading-relaxed text-muted-foreground",
      "transition-[height] duration-base ease-(--ease-out)",
      "data-[starting-style]:h-0 data-[ending-style]:h-0",
    )}
    {...props}
  >
    <div className={cn("pb-4", className)}>{children}</div>
  </AccordionPrimitive.Panel>
));
AccordionContent.displayName = "AccordionContent";

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };
